SET NOCOUNT ON;
SET STATISTICS IO ON;
SET STATISTICS TIME ON;
SELECT POCode = Q.POCode, Date = Q.Date, Remarks = Q.Remarks, SuppCode=Q.SuppCode, SupplierAliasName=A.AliasName, SupplierName=A.Name, ICode = I.ICode, ItemAliasName=I.CustomICode, ItemName=I.Name, Manufacturer=M.Name, POQty = ISNULL(SUM(Q.POQty), 0), POBonus = ISNULL(SUM(Q.POBonus), 0), PurQty = ISNULL(SUM(Q.PurQty), 0), PurBonus = ISNULL(SUM(Q.PurBonus), 0), NetQty = ISNULL(SUM(Q.POQty - Q.PurQty), 0), NetBonus = ISNULL(SUM(Q.POBonus - Q.PurBonus), 0) FROM Item I, Manufacturer M, Accounts A, (SELECT POCode = POH.POCode, Date = POH.Date, Remarks = POH.Remarks, SuppCode=POH.SuppCode, ICode = POD.ICode, POQty = ISNULL(SUM(POD.Qty), 0), POBonus = ISNULL(SUM(POD.BonusQty), 0), PurQty = ISNULL((SELECT SUM(PD.PackQty + PD.LooseQty) FROM PurDetail PD, PurLedger PL WHERE PL.POCode = POH.POCode AND PL.PurInvCode = PD.PurInvCode AND PD.ICode = POD.ICode), 0), PurBonus = ISNULL((SELECT SUM(PD.BonusQty) FROM PurDetail PD, PurLedger PL WHERE PL.POCode = POH.POCode AND PL.PurInvCode = PD.PurInvCode AND PD.ICode = POD.ICode), 0) FROM PurOrderDetail POD, PurOrderHeader POH WHERE POH.POCode IN (1) AND POH.POCode = POD.POCode GROUP BY POH.POCode, POH.Date, POH.Remarks, POH.SuppCode, POD.ICode UNION ALL SELECT POCode = POH.POCode, Date = POH.Date, Remarks = POH.Remarks, SuppCode = POH.SuppCode, ICode = PD.ICode, POQty = 0.0000, POBonus = 0.0000, PurQty = ISNULL(SUM(PD.PackQty + PD.LooseQty), 0), PurBonus = ISNULL(SUM(PD.BonusQty), 0) FROM PurDetail PD, PurLedger PL, PurOrderHeader POH WHERE POH.POCode IN (1) AND POH.POCode = PL.POCode AND PL.PurInvCode = PD.PurInvCode AND PD.ICode NOT IN (SELECT POD.ICode FROM PurOrderDetail POD WHERE POD.POCode = POH.POCode) GROUP BY POH.POCode, POH.Date, POH.Remarks, POH.SuppCode, PD.ICode) Q WHERE (Q.POQty - Q.PurQty <> 0 OR Q.POBonus - Q.PurBonus <> 0) AND Q.ICode = I.ICode AND Q.SuppCode = A.AccCode AND I.ManfCode = M.ManfCode GROUP BY Q.POCode, Q.Date, Q.Remarks, Q.SuppCode, A.AliasName, A.Name, Q.ICode, I.ICode, I.CustomICode, I.Name, M.Name ORDER BY SupplierName, Q.POCode, I.Name;
